import Foundation
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif
import HueBoardKit

private final class RedirectRejectingDelegate:NSObject,URLSessionTaskDelegate,@unchecked Sendable{
    func urlSession(_ session:URLSession,task:URLSessionTask,willPerformHTTPRedirection response:HTTPURLResponse,newRequest request:URLRequest,completionHandler:@escaping(URLRequest?)->Void){completionHandler(nil)}
}
private actor HueRequestPacer{
    private let clock=ContinuousClock(),minimum:Duration;private var next:ContinuousClock.Instant
    init(minimum:Duration = .milliseconds(175)){self.minimum=minimum;next=clock.now}
    func wait()async throws{let now=clock.now;if now<next{try await Task.sleep(until:next,clock:clock)};next=max(clock.now,next)+minimum}
}

public actor HueBridgeClient {
    private let session:URLSession,encoder=JSONEncoder(),decoder=JSONDecoder();private let pacer=HueRequestPacer()
    public init(){let c=URLSessionConfiguration.ephemeral;c.timeoutIntervalForRequest=8;c.timeoutIntervalForResource=15
#if !canImport(FoundationNetworking)
        c.waitsForConnectivity=false
#endif
        c.httpAdditionalHeaders=["Accept":"application/json"];session=URLSession(configuration:c,delegate:RedirectRejectingDelegate(),delegateQueue:nil)}
    public func discover()async throws->[HueBridgeCandidate]{guard let url=URL(string:"https://discovery.meethue.com/") else{throw HueBoardError.network("Hue discovery URL is invalid.")};let(data,response)=try await session.data(from:url);try validate(response,data:data);return try decoder.decode([HueDiscoveryRecord].self,from:data).map(\.candidate).filter{HueBridgeHostValidator.isAllowed($0.host)}}
    public func probe(candidate:HueBridgeCandidate)async throws->BridgeProfile{guard HueBridgeHostValidator.isAllowed(candidate.host) else{throw HueBoardError.network("Bridge host is outside the private LAN allowlist.")};let provisional=try BridgeProfile(bridgeID:candidate.id,host:candidate.host,port:candidate.port);let data=try await requestData(profile:provisional,method:"GET",path:"/api/config",credential:nil,body:nil);let c=try decoder.decode(HueBridgeConfiguration.self,from:data);guard let id=c.bridgeID,!id.isEmpty else{throw HueBoardError.invalidResponse("This host did not identify itself as a Hue Bridge.")};return try .init(bridgeID:id,host:candidate.host,port:candidate.port,modelID:c.modelID,apiVersion:c.apiVersion)}
    public func pair(profile:BridgeProfile)async throws->HueBridgeCredential{struct Req:Encodable{let devicetype:String;let generateclientkey:Bool};let data=try await requestData(profile:profile,method:"POST",path:"/api",credential:nil,body:try encoder.encode(Req(devicetype:"hue_board#iphone",generateclientkey:true)));let rows=try decoder.decode([HuePairingEntry].self,from:data);if let s=rows.compactMap(\.success).first{return .init(bridgeID:profile.bridgeID,applicationKey:s.username,clientKey:s.clientKey)};throw HueBoardError.authorization(rows.compactMap(\.error?.description).first ?? "Press the Bridge button and try again.")}
    public func inventory(profile:BridgeProfile,credential:HueBridgeCredential,outputLimits:[HueResourceID:Double]=[:])async throws->[HueArea]{async let rooms:[HueAreaResource]=resources("room",profile:profile,credential:credential);async let zones:[HueAreaResource]=resources("zone",profile:profile,credential:credential);async let lights:[HueLightResource]=resources("light",profile:profile,credential:credential);async let devices:[HueDeviceResource]=resources("device",profile:profile,credential:credential);return try await HueInventoryBuilder.build(rooms:rooms,zones:zones,lights:lights,devices:devices,outputLimits:outputLimits)}
    public func scene(id:HueResourceID,profile:BridgeProfile,credential:HueBridgeCredential)async throws->HueSceneResource?{let rows:[HueSceneResource]=try await resources("scene/\(id.rawValue)",profile:profile,credential:credential);return rows.first{$0.id==id}}
    public func createScene(_ scene:HueSceneCreateRequest,profile:BridgeProfile,credential:HueBridgeCredential)async throws->HueResourceID{let r:HueAPIResponse<HueResourceAcknowledgement>=try await v2(profile:profile,method:"POST",resource:"scene",credential:credential,body:scene);guard let id=r.data.first(where:{$0.resourceType=="scene"})?.resourceID ?? r.data.first?.resourceID else{throw HueBoardError.invalidResponse("Bridge returned no scene identifier.")};return id}
    public func updateScene(id:HueResourceID,scene:HueSceneUpdateRequest,profile:BridgeProfile,credential:HueBridgeCredential)async throws{let r:HueAPIResponse<HueResourceAcknowledgement>=try await v2(profile:profile,method:"PUT",resource:"scene/\(id.rawValue)",credential:credential,body:scene);try acknowledge(r.data,id:id)}
    public func recallScene(id:HueResourceID,profile:BridgeProfile,credential:HueBridgeCredential)async throws{let r:HueAPIResponse<HueResourceAcknowledgement>=try await v2(profile:profile,method:"PUT",resource:"scene/\(id.rawValue)",credential:credential,body:HueSceneRecallRequest());try acknowledge(r.data,id:id)}
    public func updateLight(id:HueResourceID,action:HueLightAction,profile:BridgeProfile,credential:HueBridgeCredential)async throws{try await pacer.wait();let r:HueAPIResponse<HueResourceAcknowledgement>=try await v2(profile:profile,method:"PUT",resource:"light/\(id.rawValue)",credential:credential,body:action);try acknowledge(r.data,id:id)}
    private struct Empty:Encodable{}
    private func resources<V:Codable&Sendable>(_ resource:String,profile:BridgeProfile,credential:HueBridgeCredential)async throws->[V]{let r:HueAPIResponse<V>=try await v2(profile:profile,method:"GET",resource:resource,credential:credential,body:Optional<Empty>.none);return r.data}
    private func v2<R:Codable&Sendable,B:Encodable>(profile:BridgeProfile,method:String,resource:String,credential:HueBridgeCredential,body:B?)async throws->HueAPIResponse<R>{let data=try await requestData(profile:profile,method:method,path:"/clip/v2/resource/\(resource)",credential:credential,body:try body.map{try encoder.encode($0)});let r=try decoder.decode(HueAPIResponse<R>.self,from:data);if let e=r.errors.first{throw HueBoardError.invalidResponse(e.description)};return r}
    private func requestData(profile:BridgeProfile,method:String,path:String,credential:HueBridgeCredential?,body:Data?)async throws->Data{guard HueBridgeHostValidator.isAllowed(profile.host),let url=URL(string:"https://\(profile.displayHost)\(path)") else{throw HueBoardError.network("Invalid Bridge URL.")};var request=URLRequest(url:url);request.httpMethod=method;request.timeoutInterval=8;request.setValue("application/json",forHTTPHeaderField:"Accept");if let credential{request.setValue(credential.applicationKey,forHTTPHeaderField:"hue-application-key")};if let body{request.httpBody=body;request.setValue("application/json",forHTTPHeaderField:"Content-Type")};do{let(data,response)=try await session.data(for:request);try validate(response,data:data);return data}catch let e as HueBoardError{throw e}catch is CancellationError{throw HueBoardError.cancelled}catch{throw HueBoardError.network("Cannot reach Hue Bridge over HTTPS: \(error.localizedDescription)")}}
    private func validate(_ response:URLResponse,data:Data)throws{guard let r=response as? HTTPURLResponse else{throw HueBoardError.invalidResponse("No HTTP response.")};switch r.statusCode{case 200..<300:return;case 401,403:throw HueBoardError.authorization("Bridge rejected the application key (HTTP \(r.statusCode)).");case 429:throw HueBoardError.network("Bridge asked Hue Board to slow down.");default:throw HueBoardError.invalidResponse("Bridge request failed (HTTP \(r.statusCode)). \(String(data:data,encoding:.utf8)?.prefix(160) ?? "")")}}
    private func acknowledge(_ rows:[HueResourceAcknowledgement],id:HueResourceID)throws{guard rows.contains(where:{$0.resourceID==id}) else{throw HueBoardError.invalidResponse("Bridge did not acknowledge the expected resource. Treat the outcome as uncertain.")}}
}
